var ls = draw.text('ℓ_s').font({ size: 26, family: font.family, style: 'italic' }).move(18, ySens - 4);

/* ── Scene axis (0 → 12, left to right) ── */
var axY = yScene - 26;
draw.line(X0 - 10, axY, X0 + N * CW + 26, axY).stroke({ color: '#000', width: 1.5 });
draw.polygon([[X0 + N * CW + 34, axY], [X0 + N * CW + 22, axY - 5], [X0 + N * CW + 22, axY + 5]]).fill('#000');
draw.text('n').font({ size: 18, family: font.family, style: 'italic' }).move(X0 + N * CW + 40, axY - 12);
for (var t = 0; t < N; t++) {
  draw.line(cx(t), axY - 6, cx(t), axY + 6).stroke({ color: '#000', width: 1.2 });
  var lab = (t === 4) ? '…' : String(t);
  if (t <= 3 || t === 12) draw.text(lab).font({ size: 15, family: font.family }).center(cx(t), axY - 20);
}

/* ── Scene cells ── */
var sceneCells = [], sceneIdx = [];
for (var s = 0; s < N; s++) {
  sceneCells.push(draw.rect(CW, cellH).move(X0 + s * CW, yScene).fill('#fff').stroke({ color: '#000', width: 1.5 }));
