  drawSensorAxis();
}
function showStep(k) {
  curStep = Math.max(0, Math.min(steps.length - 1, k));
  steps[curStep].s();
  document.getElementById('demoNarration').textContent = steps[curStep].n;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
}
function nextStep() { showStep(curStep + 1); }
function prevStep() { showStep(curStep - 1); }
showStep(0);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

