draw.text('Aperture').font({ size: 20, family: font.family }).move(rowR + 14, yOcc - 4);
draw.text('Camera sensor').font({ size: 20, family: font.family }).move(rowR + 14, ySens - 2);
draw.text('ℓ_w').font({ size: 26, family: font.family, style: 'italic' }).move(56, yScene - 2);
draw.text('ℓ_s').font({ size: 26, family: font.family, style: 'italic' }).move(56, ySens - 2);

/* ── Scene axis (0 → 12, left to right) ── */
