draw.line(X0 - 10, axY, rowR + 26, axY).stroke({ color: '#000', width: 1.5 });
draw.polygon([[rowR + 34, axY], [rowR + 22, axY - 5], [rowR + 22, axY + 5]]).fill('#000');
draw.text('n').font({ size: 18, family: font.family, style: 'italic' }).move(rowR + 40, axY - 12);
for (var t = 0; t < N; t++) {
  draw.line(cx(t), axY - 6, cx(t), axY + 6).stroke({ color: '#000', width: 1.2 });
  if (t <= 3 || t === 4 || t === N - 1) {
