}

/* ── Occluder with pinhole gap ── */
var gapW = 26;
draw.rect(xPin - gapW / 2 - (X0 - 90), 16).move(X0 - 90, yOcc).fill('#111');
draw.rect(rowR + 90 - (xPin + gapW / 2), 16).move(xPin + gapW / 2, yOcc).fill('#111');
