// @FIGURE_CODE_BEGIN
var N = 13;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 940, 560);

var CW = 44, X0 = 210;                // cell width, left edge of rows (room for left labels)
var yScene = 86, yOcc = 268, ySens = 452, cellH = 28;
var xPin = X0 + (N * CW) / 2;         // exact center so reversal is exact
function cx(i) { return X0 + i * CW + CW / 2; }
var rowR = X0 + N * CW;               // right edge of cell rows

var w = []; for (var i = 0; i < N; i++) w.push(0); w[2] = 1;
var aligned = false;

var font = { family: 'Georgia, serif' };

/* ── Static labels (all inside the viewbox) ── */
draw.text('Scene').font({ size: 22, family: font.family }).move(rowR + 18, yScene - 2);
draw.text('Occluder').font({ size: 20, family: font.family }).move(64, yOcc - 6);
draw.text('Aperture').font({ size: 20, family: font.family }).move(rowR + 18, yOcc - 6);
draw.text('Camera sensor').font({ size: 20, family: font.family }).move(rowR + 18, ySens - 2);
draw.text('ℓ_w').font({ size: 28, family: font.family, style: 'italic' }).move(140, yScene - 2);
draw.text('ℓ_s').font({ size: 28, family: font.family, style: 'italic' }).move(140, ySens - 2);

/* ── Scene axis (0 → 12, left to right) ── */
var axY = yScene - 30;
draw.line(X0 - 12, axY, rowR + 30, axY).stroke({ color: '#000', width: 1.5 });
draw.polygon([[rowR + 38, axY], [rowR + 24, axY - 5], [rowR + 24, axY + 5]]).fill('#000');
draw.text('n').font({ size: 20, family: font.family, style: 'italic' }).move(rowR + 44, axY - 13);
for (var t = 0; t < N; t++) {
  draw.line(cx(t), axY - 7, cx(t), axY + 7).stroke({ color: '#000', width: 1.2 });
  if (t <= 3 || t === 4 || t === N - 1) {
    var lab = (t === 4) ? '…' : String(t);
    draw.text(lab).font({ size: 18, family: font.family }).center(cx(t), axY - 23);
  }
}

/* ── Scene cells ── */
var sceneCells = [];
for (var s = 0; s < N; s++) {
  sceneCells.push(draw.rect(CW, cellH).move(X0 + s * CW, yScene).fill('#fff').stroke({ color: '#000', width: 1.5 }));
}

/* ── Occluder with pinhole gap (overhang roughly matches row width) ── */
var gapW = 26, occL = X0 - 30, occR = rowR + 30;
draw.rect(xPin - gapW / 2 - occL, 16).move(occL, yOcc).fill('#111');
draw.rect(occR - (xPin + gapW / 2), 16).move(xPin + gapW / 2, yOcc).fill('#111');
