/* ── Sensor cells ── */
var sensCells = [];
for (var q = 0; q < N; q++) {
  sensCells.push(draw.rect(CW, cellH).move(X0 + q * CW, ySens).fill('#fff').stroke({ color: '#000', width: 1.5 }));
}

/* ── Sensor axis (labels depend on orientation) ── */
var sAxY = ySens + cellH + 26;
var sensAxisG = draw.group();
function drawSensorAxis() {
  sensAxisG.clear();
  var xL = X0 - 12, xR = rowR + 30;
  sensAxisG.line(xL, sAxY, xR, sAxY).stroke({ color: '#000', width: 1.5 });
  var t, n;
  if (!aligned) { // reversed: arrow points left, labels 12 … 0
    sensAxisG.polygon([[xL - 10, sAxY], [xL + 4, sAxY - 5], [xL + 4, sAxY + 5]]).fill('#000');
    sensAxisG.text('n').font({ size: 20, family: font.family, style: 'italic' }).move(xL - 32, sAxY - 13);
    for (t = 0; t < N; t++) {
      sensAxisG.line(cx(t), sAxY - 7, cx(t), sAxY + 7).stroke({ color: '#000', width: 1.2 });
      n = N - 1 - t;
