drawSensorAxis();

/* ── Rays ── */
var rayG = draw.group();
function arrowhead(x1, y1, x2, y2, g, op) {
  var a = Math.atan2(y2 - y1, x2 - x1), L = 12;
  g.polygon([[x2, y2],
    [x2 - L * Math.cos(a - 0.35), y2 - L * Math.sin(a - 0.35)],
