    var sx = cx(i), sy = yScene + cellH;
    // through-pinhole ray to sensor cell N-1-i
    var hx = cx(N - 1 - i);
    rayG.line(sx, sy, xPin, yOcc + 8).stroke({ color: '#e00', width: 2, opacity: op });
    rayG.line(xPin, yOcc + 8, hx, ySens - 2).stroke({ color: '#e00', width: 2, opacity: op });
    arrowhead(xPin, yOcc + 8, hx, ySens - 2, rayG, op);
    if (i === bi) {
      // rays blocked by the occluder
      var offs = [-150, -100, -55, 55, 105, 160];
