        arrowhead(sx, sy, ex, ey, rayG, op * 0.85);
      }
      // rays escaping into open space: radiation goes in all directions
      var open = [[sx - 185, yOcc + 120], [sx - 165, yOcc + 20], [sx + 320, yOcc + 130]];
      for (var m = 0; m < open.length; m++) {
        var ox = open[m][0], oy = open[m][1];
        // clip at occluder level if the ray would cross the bar
        if (oy > yOcc) {
          var tc = (yOcc - 2 - sy) / (oy - sy);
          var xc = sx + (ox - sx) * tc;
          if (xc > occL && xc < occR && Math.abs(xc - xPin) > gapW / 2) { ox = xc; oy = yOcc - 2; }
        }
        rayG.line(sx, sy, ox, oy).stroke({ color: '#e00', width: 1.6, opacity: op * 0.85 });
        arrowhead(sx, sy, ox, oy, rayG, op * 0.85);
      }
    }
  }
}
